/**
 * Growth plans in Airtable: one row per personal deck, in its own table
 * (AIRTABLE_PLANS_TABLE_ID) in the same base as leads and briefs.
 *
 * Columns: Token, Status, Source, Name, Company, Email, Consent, Lead,
 * Plan, Generated by, Created, Sent at, Variant, Follow-up due,
 * Follow-up sent, Opened at, Booked at, Paid at.
 */
import type { LeadInput, PlanDeck } from './deck'

const BASE = process.env.AIRTABLE_BASE_ID
const TABLE = process.env.AIRTABLE_PLANS_TABLE_ID
const TOKEN = process.env.AIRTABLE_TOKEN
const API = `https://api.airtable.com/v0/${BASE}/${TABLE}`

export type PlanStatus = 'Generating' | 'Needs review' | 'Sent' | 'Unsubscribed' | 'Failed'
export type Variant = 'invite' | 'booked' | 'checkout'

export type PlanRecord = {
  id: string
  token: string
  status: PlanStatus
  lead: LeadInput
  deck: PlanDeck | null
  by: string
  created?: string
  sentAt?: string
  variant?: Variant
  followUpDue?: string
  followUpSent?: string
  openedAt?: string
  bookedAt?: string
  paidAt?: string
}

export function plansConfigured() {
  return Boolean(BASE && TABLE && TOKEN)
}

const headers = () => ({ Authorization: `Bearer ${TOKEN}`, 'Content-Type': 'application/json' })

function toRecord(r: { id: string; fields: Record<string, unknown> }): PlanRecord {
  const f = r.fields
  const json = <T,>(v: unknown): T | null => { try { return typeof v === 'string' ? JSON.parse(v) as T : null } catch { return null } }
  const s = (k: string) => (typeof f[k] === 'string' ? (f[k] as string) : undefined)
  return {
    id: r.id,
    token: s('Token') ?? '',
    status: (s('Status') ?? 'Generating') as PlanStatus,
    lead: json<LeadInput>(f['Lead']) ?? { source: 'Quiz', name: s('Name') ?? '', company: s('Company') ?? '', email: s('Email') ?? '', consent: f['Consent'] === true, answers: {} },
    deck: json<PlanDeck>(f['Plan']),
    by: s('Generated by') ?? '',
    created: s('Created'),
    sentAt: s('Sent at'),
    variant: s('Variant') as Variant | undefined,
    followUpDue: s('Follow-up due'),
    followUpSent: s('Follow-up sent'),
    openedAt: s('Opened at'),
    bookedAt: s('Booked at'),
    paidAt: s('Paid at'),
  }
}

export async function createPlan(token: string, lead: LeadInput): Promise<string> {
  const res = await fetch(API, {
    method: 'POST',
    headers: headers(),
    body: JSON.stringify({
      typecast: true,
      records: [{ fields: {
        Token: token, Status: 'Generating', Source: lead.source, Name: lead.name, Company: lead.company,
        Email: lead.email, Consent: lead.consent, Lead: JSON.stringify(lead), Created: new Date().toISOString(),
      } }],
    }),
  })
  if (!res.ok) throw new Error(`Airtable ${res.status}: ${await res.text()}`)
  return (await res.json()).records[0].id
}

export async function updatePlan(id: string, fields: Record<string, unknown>) {
  const res = await fetch(`${API}/${id}`, { method: 'PATCH', headers: headers(), body: JSON.stringify({ fields, typecast: true }) })
  if (!res.ok) throw new Error(`Airtable ${res.status}: ${await res.text()}`)
}

async function select(formula: string, sortNewest = true): Promise<PlanRecord[]> {
  const q = new URLSearchParams({ filterByFormula: formula, pageSize: '50' })
  if (sortNewest) { q.set('sort[0][field]', 'Created'); q.set('sort[0][direction]', 'desc') }
  const res = await fetch(`${API}?${q}`, { headers: headers(), cache: 'no-store' })
  if (!res.ok) throw new Error(`Airtable ${res.status}: ${await res.text()}`)
  return (await res.json()).records.map(toRecord)
}

/** Tokens are generated hex, so they are safe to drop into a formula. */
export async function findByToken(token: string): Promise<PlanRecord | null> {
  if (!/^[a-f0-9]{24,64}$/.test(token)) return null
  return (await select(`{Token}='${token}'`, false))[0] ?? null
}

export async function findLatestByEmail(email: string): Promise<PlanRecord | null> {
  const e = email.trim().toLowerCase().replace(/'/g, "\\'")
  return (await select(`LOWER({Email})='${e}'`))[0] ?? null
}

/** Sent plans whose follow-up is due and that haven't booked, paid or opted out. */
export async function dueFollowUps(): Promise<PlanRecord[]> {
  return select(`AND({Status}='Sent', {Consent}, {Follow-up due}, IS_BEFORE({Follow-up due}, NOW()), NOT({Follow-up sent}), NOT({Booked at}), NOT({Paid at}))`, false)
}
